"% System matrices
A_cl = [-0.8, 1.0; -6.2, -1.9];
B_cl = [0.0; 1.0];
C_cl = [1.0, 0.0];

% Simulation parameters
dt = 0.01;
T = 30;
t = 0:dt:T;
N = length(t);

% Exact zero-order-hold discretization
I = eye(size(A_cl));
Ad = expm(A_cl * dt);
Bd = A_cl \ ((Ad - I) * B_cl);

% Simulation
x = zeros(2, N);
y = zeros(1, N);
u = 1; % Unit step input

for k = 1:N-1
    y(k) = C_cl * x(:, k);
    x(:, k+1) = Ad * x(:, k) + Bd * u;
end
% Final output
y(N) = C_cl * x(:, N);

% Steady state (DC value)
y_inf = -C_cl * (A_cl \ B_cl);

% --- Metric Computations ---

% 1. Percent Overshoot
max_y = max(y);
overshoot_pct = (max_y - y_inf) / abs(y_inf) * 100;

% 2. Rise Time (10% - 90%) with linear interpolation
target_10 = 0.1 * y_inf;
target_90 = 0.9 * y_inf;

% Find 10% crossing time
idx_10 = find(y >= target_10, 1);
if ~isempty(idx_10) && idx_10 > 1
    t10 = t(idx_10-1) + (target_10 - y(idx_10-1)) * (t(idx_10) - t(idx_10-1)) / (y(idx_10) - y(idx_10-1));
else
    t10 = t(1);
end

% Find 90% crossing time
idx_90 = find(y >= target_90, 1);
if ~isempty(idx_90) && idx_90 > 1
    t90 = t(idx_90-1) + (target_90 - y(idx_90-1)) * (t(idx_90) - t(idx_90-1)) / (y(idx_90) - y(idx_90-1));
else
    t90 = t(end);
end

rise_time_s = t90 - t10;

% 3. Settling Time (2%)
% Time of the LAST grid sample where |y - y_inf| > 0.02 * |y_inf|
tol = 0.02 * abs(y_inf);
violation_indices = find(abs(y - y_inf) > tol);

if isempty(violation_indices)
    settling_time_s = 0;
else
    settling_time_s = t(violation_indices(end));
end

% Write results to JSON
results = struct();
results.rise_time_s = rise_time_s;
results.overshoot_pct = overshoot_pct;
results.settling_time_s = settling_time_s;

fid = fopen('result.json', 'w');
fprintf(fid, '%s', jsonencode(results));
fclose(fid);"
